package com.northstar.crm.ui;
import com.northstar.crm.service.AccountService;import com.vaadin.flow.component.UI;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.VerticalLayout;import com.vaadin.flow.component.textfield.PasswordField;import com.vaadin.flow.router.*;import com.vaadin.flow.server.auth.AnonymousAllowed;
@Route("reset-password")@PageTitle("Reset password · Northstar")@AnonymousAllowed public class ResetPasswordView extends VerticalLayout implements BeforeEnterObserver {private final AccountService accounts;private String token="";public ResetPasswordView(AccountService a){accounts=a;addClassName("public-form");var password=new PasswordField("New password");password.setHelperText("12+ characters with upper, lower and number");password.setWidthFull();var confirm=new PasswordField("Confirm password");confirm.setWidthFull();var card=new VerticalLayout(new H1("Choose a new password"),new Paragraph("This reset link expires after one hour and works once."),password,confirm,UiKit.primary("Reset password",e->{try{if(!password.getValue().equals(confirm.getValue()))throw new IllegalArgumentException("Passwords do not match");accounts.resetPassword(token,password.getValue());UiKit.success("Password reset. You can now sign in.");UI.getCurrent().navigate(LoginView.class);}catch(Exception ex){UiKit.error(ex);}}));card.addClassName("login-card");add(card);setSizeFull();setAlignItems(Alignment.CENTER);setJustifyContentMode(JustifyContentMode.CENTER);}@Override public void beforeEnter(BeforeEnterEvent e){token=e.getLocation().getQueryParameters().getSingleParameter("token").orElse("");}}
